package api

import("context";"crypto/subtle";"encoding/json";"errors";"io";"log/slog";"net/http";"regexp";"runtime/debug";"strconv";"time";"github.com/jackc/pgx/v5/pgxpool";"github.com/REinstall-SyS/WaitlistFair/internal/appointments";"github.com/REinstall-SyS/WaitlistFair/internal/auth";"github.com/REinstall-SyS/WaitlistFair/internal/config";"github.com/REinstall-SyS/WaitlistFair/internal/persistence")
type Server struct{DB *pgxpool.Pool;Config config.Config;Appointments *appointments.Service;Auth *auth.Service;Log *slog.Logger}
type badRequest string
func(e badRequest)Error()string{return string(e)}
type endpoint func(http.ResponseWriter,*http.Request)error
type contextKey struct{}
var uuidPattern=regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
func validID(id string)bool{return uuidPattern.MatchString(id)}
func JSON(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func decode(w http.ResponseWriter,r *http.Request,dst any)error{if r.Header.Get("Content-Type")!="application/json"{return badRequest("use application/json")};r.Body=http.MaxBytesReader(w,r.Body,65536);d:=json.NewDecoder(r.Body);d.DisallowUnknownFields();if e:=d.Decode(dst);e!=nil{return badRequest("invalid request body")};if e:=d.Decode(&struct{}{});e!=io.EOF{return badRequest("send one JSON object")};return nil}
func identity(r *http.Request)auth.Identity{return r.Context().Value(contextKey{}).(auth.Identity)}
func(s *Server)actor(r *http.Request)(appointments.Actor,error){u:=identity(r);a:=appointments.Actor{UserID:u.ID,OrgID:r.PathValue("org")};if !validID(a.OrgID){return a,badRequest("invalid organization ID")};e:=s.DB.QueryRow(r.Context(),`SELECT role FROM memberships WHERE organization_id=$1 AND user_id=$2 AND enabled`,a.OrgID,a.UserID).Scan(&a.Role);if e!=nil{return a,appointments.ErrForbidden};return a,nil}
func(s *Server)wrap(fn endpoint,protected bool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){ctx,cancel:=context.WithTimeout(r.Context(),20*time.Second);defer cancel();r=r.WithContext(ctx);if protected{cookie,e:=r.Cookie("wf_session");if e!=nil{JSON(w,401,map[string]string{"error":"Please sign in to continue."});return};u,e:=s.Auth.Session(ctx,cookie.Value);if e!=nil{JSON(w,401,map[string]string{"error":"Your session has ended. Please sign in again."});return};r=r.WithContext(context.WithValue(ctx,contextKey{},u));if r.Method!="GET"&&r.Method!="HEAD"{if subtle.ConstantTimeCompare([]byte(r.Header.Get("X-CSRF-Token")),[]byte(u.CSRF))!=1{JSON(w,403,map[string]string{"error":"Refresh this page and try again."});return}}};if e:=fn(w,r);e!=nil{s.failure(w,r,e)}}}
func(s *Server)failure(w http.ResponseWriter,r *http.Request,e error){status,message:=500,"Something went wrong. Please try again.";var b badRequest;switch{case errors.As(e,&b):status,message=400,b.Error();case errors.Is(e,appointments.ErrForbidden):status,message=403,"You do not have permission to do that.";case errors.Is(e,appointments.ErrNotFound):status,message=404,"This record could not be found.";case errors.Is(e,appointments.ErrConflict):status,message=409,e.Error()};if status==500{s.Log.Error("request failed","path",r.URL.Path,"error",e.Error())};JSON(w,status,map[string]string{"error":message})}
func(s *Server)Handler()http.Handler{
 mux:=http.NewServeMux();register:=func(pattern string,fn endpoint,protected bool){mux.HandleFunc(pattern,s.wrap(fn,protected))}
 register("GET /healthz",func(w http.ResponseWriter,r *http.Request)error{ctx,cancel:=context.WithTimeout(r.Context(),time.Second);defer cancel();if e:=s.DB.Ping(ctx);e!=nil{JSON(w,503,map[string]string{"status":"unavailable"});return nil};JSON(w,200,map[string]string{"status":"ok"});return nil},false)
 register("POST /api/auth/request",s.requestLink,false);register("POST /api/auth/verify",s.verify,false);register("POST /api/auth/logout",s.logout,true);register("GET /api/me",s.me,true)
 register("PATCH /api/account",s.profile,true);register("DELETE /api/account",s.deleteAccount,true);register("POST /api/organizations",s.createOrg,true)
 register("GET /api/orgs/{org}/dashboard",s.dashboard,true);register("GET /api/orgs/{org}/decisions",s.decisions,true);register("GET /api/orgs/{org}/audit",s.audit,true);register("GET /api/orgs/{org}/metrics",s.metrics,true)
 register("POST /api/orgs/{org}/slots",s.createSlot,true);register("POST /api/orgs/{org}/slots/{id}/book",s.book,true);register("POST /api/orgs/{org}/slots/{id}/cancel",s.cancel,true);register("POST /api/orgs/{org}/slots/{id}/close",s.closeSlot,true)
 register("POST /api/orgs/{org}/waitlist",s.joinWaitlist,true);register("PATCH /api/orgs/{org}/waitlist/{id}",s.updateWaitlist,true)
 register("POST /api/orgs/{org}/offers/{id}/accept",s.accept,true);register("POST /api/orgs/{org}/offers/{id}/decline",s.decline,true)
 register("POST /api/orgs/{org}/services",s.createService,true);register("POST /api/orgs/{org}/members",s.addMember,true);register("POST /api/orgs/{org}/tutors",s.addTutor,true);register("PATCH /api/orgs/{org}/settings",s.orgSettings,true)
 return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){start:=time.Now();requestID:=auth.Random()[:16];w.Header().Set("X-Request-ID",requestID);w.Header().Set("Cache-Control","no-store");w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("Referrer-Policy","no-referrer");defer func(){if v:=recover();v!=nil{s.Log.Error("handler panic","request_id",requestID,"stack",string(debug.Stack()));JSON(w,500,map[string]string{"error":"Something went wrong."})};s.Log.Info("http request","method",r.Method,"path",r.URL.Path,"duration_ms",time.Since(start).Milliseconds(),"request_id",requestID)}();if r.Method!="GET"&&r.Method!="HEAD"&&r.Header.Get("Origin")!=s.Config.AppURL{JSON(w,403,map[string]string{"error":"Request origin is not allowed."});return};mux.ServeHTTP(w,r)})
}
func(s *Server)rows(r *http.Request,query string,args ...any)([]map[string]any,error){return persistence.JSONRows(r.Context(),s.DB,query,args...)}
func pagination(r *http.Request)(int,int){limit,offset:=50,0;if n,e:=strconv.Atoi(r.URL.Query().Get("limit"));e==nil&&n>0{limit=min(n,100)};if n,e:=strconv.Atoi(r.URL.Query().Get("offset"));e==nil&&n>=0{offset=min(n,100000)};return limit,offset}
func requireAdmin(a appointments.Actor)error{if a.Role!="admin"{return appointments.ErrForbidden};return nil}
func pathID(r *http.Request)(string,error){id:=r.PathValue("id");if !validID(id){return "",badRequest("invalid record ID")};return id,nil}
